export function Animation({
  property = "{{property}}",
  duration = {{duration}},
  loop = {{loop}},
  accent = "{{accent}}",
  label = "{{label}}",
}) {
  return (
    <div>
      <div data-property={property} style={{ position: "relative", width: "100%", maxWidth: 320, height: 110, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, overflow: "hidden", fontFamily: "system-ui, sans-serif", color: "#241430" }}>
        <span className={loop ? "chip chip--loop" : "chip"} style={{ position: "absolute", top: "50%", left: 16, transform: "translateY(-50%)", display: "inline-block", padding: "8px 14px", borderRadius: 999, fontWeight: 600, background: accent, color: "#241430" }}>
          {label}
        </span>
      </div>
      <p style={{ margin: "8px 0 0", fontSize: 13, color: "#241430aa" }}>Property animated: <strong>{property}</strong> &middot; {duration}ms</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          [data-property="position"] .chip { animation: mot-anim-pos ${duration}ms ease-in-out infinite; }
          [data-property="opacity"] .chip { animation: mot-anim-op ${duration}ms ease-in-out infinite; }
          [data-property="colour"] .chip { animation: mot-anim-col ${duration}ms ease-in-out infinite; }
          [data-property="scale"] .chip { animation: mot-anim-scale ${duration}ms ease-in-out infinite; }
          .chip:not(.chip--loop) { animation-iteration-count: 1; animation-fill-mode: forwards; }
          @keyframes mot-anim-pos { 0%,100% { left: 16px; } 50% { left: 220px; } }
          @keyframes mot-anim-op { 0%,100% { opacity: 1; } 50% { opacity: .25; } }
          @keyframes mot-anim-col { 0%,100% { background: #A8E6C1; color: #241430; } 50% { background: #241430; color: #FAF7F2; } }
          @keyframes mot-anim-scale { 0%,100% { transform: translateY(-50%) scale(1); } 50% { transform: translateY(-50%) scale(1.4); } }
        }
      `}</style>
    </div>
  );
}
